"use server";

// Attractions list — yeni apiv3 `attractions` tablosundan beslenir (X-App-Token
// gizli kaldığından server action; istemci sayfalama bunu çağırır).
export default async function getAttractions({ page }: { page: number; }) {
    if (!process.env.NEXT_PUBLIC_APIV3_URL) {
        return { data: [], meta: { total: 0, current_page: 1, last_page: 1, per_page: 9 } };
    }

    try {
        const res = await fetch(
            `${process.env.NEXT_PUBLIC_APIV3_URL}/attractions?page=${page}`,
            {
                cache: "force-cache",
                method: "GET",
                headers: {
                    "Content-type": "application/json",
                    "Content-Language": "en",
                    "Accept": "application/json",
                    "X-App-Token": process.env.APIV3_APP_TOKEN ?? "",
                }
            }
        );

        if (!res.ok) {
            return { data: [], meta: { total: 0, current_page: 1, last_page: 1, per_page: 9 } };
        }

        return res.json();
    } catch {
        return { data: [], meta: { total: 0, current_page: 1, last_page: 1, per_page: 9 } };
    }
}
